1	/**
2	 * @module features/tv-dashboard/model/tvMath
3	 *
4	 * Funções PURAS do Dashboard de Crise (painel TV): pró-rata de meta,
5	 * delta semanal, classificação RAG, formatação compacta de moeda,
6	 * staleness e agregações determinísticas usadas pelo hook de dados.
7	 *
8	 * Tudo aqui é livre de I/O e testável em isolamento (`tvMath.test.ts`).
9	 */
10	
11	import type {
12	  TvBusinessHours,
13	  TvCriticalItem,
14	  TvDateRange,
15	  TvException,
16	  TvExceptionsResult,
17	  TvFreshness,
18	  TvFreshnessLevel,
19	  TvPeriod,
20	  TvRagStatus,
21	  TvRecentMove,
22	  TvStockAlertItem,
23	} from './types';
24	
25	// ─────────────────────────────────────────────────────────────────────────────
26	// Constantes de negócio
27	// ─────────────────────────────────────────────────────────────────────────────
28	
29	/**
30	 * Janela de funcionamento das LOJAS usada no pró-rata da meta (hora local,
31	 * design.md §1.6 regra 5: 10:00–22:00). AJUSTÁVEL: se o horário comercial
32	 * mudar, basta alterar aqui — pró-rata e "sem movimentação" derivam daqui.
33	 */
34	export const TV_BUSINESS_HOURS: TvBusinessHours = { start: 10, end: 22 };
35	
36	/**
37	 * Janela de produção da FÁBRICA (design.md §1.6 regra 5 + §5: 06:00–18:00).
38	 * Usada TANTO no RAG da fábrica quanto no alerta visual do card.
39	 */
40	export const TV_FACTORY_HOURS: TvBusinessHours = { start: 6, end: 18 };
41	
42	/** Horas sem movimentação (dentro da janela) que tornam a LOJA âmbar. */
43	export const NO_MOVEMENT_THRESHOLD_HOURS = 3;
44	
45	/** Horas sem bipagem (na janela de produção) que tornam a FÁBRICA âmbar (§5). */
46	export const FACTORY_NO_MOVEMENT_THRESHOLD_HOURS = 2;
47	
48	/**
49	 * Ratio pró-rata (%real / %esperado, em %) abaixo do qual a venda live fica
50	 * ÂMBAR — nunca vermelho (design.md §1.6 regra 6: ratio menor que 0,75).
51	 */
52	export const LIVE_SALES_AMBER_THRESHOLD_PCT = 75;
53	
54	/** Hora local a partir da qual a regra de venda fraca passa a valer (§1.6). */
55	export const LIVE_SALES_AMBER_FROM_HOUR = 11;
56	
57	/** Máximo de linhas exibidas na faixa de exceções. */
58	export const TV_EXCEPTIONS_LIMIT = 7;
59	
60	/** Itens do mini-feed "AGORA" por coluna de unidade. */
61	export const TV_MINI_FEED_SIZE = 3;
62	
63	/** Itens de estoque crítico exibidos na coluna (lista completa no drill-down). */
64	export const TV_CRITICAL_TOP_N = 5;
65	
66	/** Máximo de linhas do feed de movimentações no drill-down por loja. */
67	export const TV_DETAIL_FEED_LIMIT = 50;
68	
69	// ─────────────────────────────────────────────────────────────────────────────
70	// Datas (helpers locais, sem dependência de timezone UTC)
71	// ─────────────────────────────────────────────────────────────────────────────
72	
73	/** Formata uma data como YYYY-MM-DD no fuso LOCAL (não UTC). */
74	export function toIsoDateLocal(d: Date): string {
75	  const y = d.getFullYear();
76	  const m = String(d.getMonth() + 1).padStart(2, '0');
77	  const day = String(d.getDate()).padStart(2, '0');
78	  return `${y}-${m}-${day}`;
79	}
80	
81	/** Faz parse de YYYY-MM-DD como data LOCAL (evita shift de fuso do `new Date(iso)`). */
82	export function parseIsoDateLocal(iso: string): Date {
83	  const [y, m, d] = iso.split('-').map(Number);
84	  return new Date(y, (m ?? 1) - 1, d ?? 1);
85	}
86	
87	/** Soma `days` dias a uma data, retornando nova instância. */
88	export function addDays(d: Date, days: number): Date {
89	  const out = new Date(d);
90	  out.setDate(out.getDate() + days);
91	  return out;
92	}
93	
94	/** Rótulo de defasagem "até DD/MM" para dado que não é de hoje. */
95	export function formatLaggedDateLabel(isoDate: string): string {
96	  const d = parseIsoDateLocal(isoDate);
97	  const dd = String(d.getDate()).padStart(2, '0');
98	  const mm = String(d.getMonth() + 1).padStart(2, '0');
99	  return `até ${dd}/${mm}`;
100	}
101	
102	/**
103	 * Parser do timestamp pt-BR do Degust (`ultima_atualizacao` vem como
104	 * "DD/MM/YYYY HH:mm:ss"): `new Date()` interpreta como MM/DD e FALHA para
105	 * dia maior que 12. Faz parse como data LOCAL; aceita segundos opcionais e
106	 * cai pro parse nativo para outros formatos (ex.: ISO). Inválido → null.
107	 */
108	export function parseBrDateTime(value: string | null | undefined): Date | null {
109	  if (!value) return null;
110	  const m = value.match(
111	    /^(\d{2})\/(\d{2})\/(\d{4})[ T](\d{2}):(\d{2})(?::(\d{2}))?$/,
112	  );
113	  if (m) {
114	    const [, dd, mm, yyyy, hh, mi, ss] = m;
115	    const month = Number(mm);
116	    const day = Number(dd);
117	    if (month < 1 || month > 12 || day < 1 || day > 31) return null;
118	    return new Date(
119	      Number(yyyy),
120	      month - 1,
121	      day,
122	      Number(hh),
123	      Number(mi),
124	      ss ? Number(ss) : 0,
125	    );
126	  }
127	  const fallback = new Date(value);
128	  return Number.isNaN(fallback.getTime()) ? null : fallback;
129	}
130	
131	/** Hora local "HH:mm" de um timestamp ISO ("—" para ausente/inválido). */
132	export function timeHHMMFromIso(iso: string | null | undefined): string {
133	  if (!iso) return '—';
134	  const d = new Date(iso);
135	  if (Number.isNaN(d.getTime())) return '—';
136	  const hh = String(d.getHours()).padStart(2, '0');
137	  const mm = String(d.getMinutes()).padStart(2, '0');
138	  return `${hh}:${mm}`;
139	}
140	
141	// ─────────────────────────────────────────────────────────────────────────────
142	// Ranges do filtro global de período (v3) — datas LOCAIS, puras e testáveis
143	// ─────────────────────────────────────────────────────────────────────────────
144	
145	/**
146	 * Range do filtro global (fechado [from, to], YYYY-MM-DD local):
147	 * - `today`: hoje → hoje;
148	 * - `week`: segunda-feira da semana corrente → hoje;
149	 * - `month`: dia 1º do mês corrente → hoje.
150	 */
151	export function periodRange(period: TvPeriod, now: Date): TvDateRange {
152	  const today = toIsoDateLocal(now);
153	  if (period === 'today') return { from: today, to: today };
154	  if (period === 'week') {
155	    // getDay(): 0=domingo → 0=segunda com (dow+6)%7
156	    const dowFromMonday = (now.getDay() + 6) % 7;
157	    const monday = addDays(now, -dowFromMonday);
158	    return { from: toIsoDateLocal(monday), to: today };
159	  }
160	  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
161	  return { from: toIsoDateLocal(firstOfMonth), to: today };
162	}
163	
164	/**
165	 * Período ANTERIOR equivalente para comparativos do filtro global:
166	 * - `today`: ontem → ontem;
167	 * - `week`: semana passada até o MESMO dia da semana (seg → hoje−7);
168	 * - `month`: mês passado do dia 1º até o MESMO dia do mês — clampado ao
169	 *   último dia quando o mês anterior é mais curto (31/05 → 30/04).
170	 */
171	export function previousPeriodRange(period: TvPeriod, now: Date): TvDateRange {
172	  if (period === 'today') {
173	    const yesterday = toIsoDateLocal(addDays(now, -1));
174	    return { from: yesterday, to: yesterday };
175	  }
176	  if (period === 'week') {
177	    const dowFromMonday = (now.getDay() + 6) % 7;
178	    const mondayLastWeek = addDays(now, -dowFromMonday - 7);
179	    return {
180	      from: toIsoDateLocal(mondayLastWeek),
181	      to: toIsoDateLocal(addDays(now, -7)),
182	    };
183	  }
184	  const y = now.getFullYear();
185	  const m = now.getMonth();
186	  const firstPrev = new Date(y, m - 1, 1);
187	  // `new Date(y, m, 0)` = último dia do mês ANTERIOR a `m`
188	  const lastDayPrevMonth = new Date(y, m, 0).getDate();
189	  const toPrev = new Date(y, m - 1, Math.min(now.getDate(), lastDayPrevMonth));
190	  return { from: toIsoDateLocal(firstPrev), to: toIsoDateLocal(toPrev) };
191	}
192	
193	/**
194	 * Range anterior de MESMA DURAÇÃO em dias, imediatamente antes do range
195	 * dado (drill-down com filtro custom: [from−N, from−1] para N dias).
196	 */
197	export function previousRangeSameDuration(range: TvDateRange): TvDateRange {
198	  const from = parseIsoDateLocal(range.from);
199	  const to = parseIsoDateLocal(range.to);
200	  // Math.round absorve a hora de DST (diferença 23h/25h em viradas de horário)
201	  const days = Math.round((to.getTime() - from.getTime()) / 86_400_000) + 1;
202	  return {
203	    from: toIsoDateLocal(addDays(from, -days)),
204	    to: toIsoDateLocal(addDays(to, -days)),
205	  };
206	}
207	
208	/**
209	 * Converte um range de DIAS locais em limites de TIMESTAMP para filtrar
210	 * colunas timestamptz (ex.: `perdas.data_identificacao`): início = 00:00
211	 * local do 1º dia (inclusive); fim = 00:00 local do dia SEGUINTE ao último
212	 * (exclusivo — usar `.lt`, nunca `.lte`).
213	 */
214	export function rangeToLocalDayBounds(range: TvDateRange): {
215	  startIso: string;
216	  endExclusiveIso: string;
217	} {
218	  const start = parseIsoDateLocal(range.from);
219	  const endExclusive = addDays(parseIsoDateLocal(range.to), 1);
220	  return {
221	    startIso: start.toISOString(),
222	    endExclusiveIso: endExclusive.toISOString(),
223	  };
224	}
225	
226	// ─────────────────────────────────────────────────────────────────────────────
227	// Pró-rata da meta
228	// ─────────────────────────────────────────────────────────────────────────────
229	
230	/**
231	 * Fração linear do dia comercial já decorrida em `now`.
232	 *
233	 * - Antes da abertura → 0 (não há venda esperada ainda).
234	 * - Depois do fechamento → 1 (meta integral esperada).
235	 * - Dentro da janela → interpolação linear simples (pró-rata).
236	 */
237	export function businessDayFraction(
238	  now: Date,
239	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
240	): number {
241	  const { start, end } = hours;
242	  if (end <= start) {
243	    // Janela inválida — fail fast com comportamento seguro (sem divisão por 0)
244	    return now.getHours() >= end ? 1 : 0;
245	  }
246	  const h = now.getHours() + now.getMinutes() / 60 + now.getSeconds() / 3600;
247	  if (h <= start) return 0;
248	  if (h >= end) return 1;
249	  return (h - start) / (end - start);
250	}
251	
252	/**
253	 * % da meta pró-rata: vendido / (meta diária × fração da janela decorrida).
254	 *
255	 * Retorna null quando não dá para calcular com honestidade:
256	 * - meta ausente/zerada (sem referência), ou
257	 * - antes da janela de funcionamento (esperado = 0; divisão sem sentido).
258	 */
259	export function pctOfProRataTarget(
260	  sold: number,
261	  dailyTarget: number | null | undefined,
262	  now: Date,
263	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
264	): number | null {
265	  if (dailyTarget == null || dailyTarget <= 0) return null;
266	  const fraction = businessDayFraction(now, hours);
267	  if (fraction <= 0) return null;
268	  return (sold / (dailyTarget * fraction)) * 100;
269	}
270	
271	/**
272	 * % da meta de um dia COMPLETO (sem pró-rata) — usado para canal defasado,
273	 * cujo dia de referência já encerrou.
274	 */
275	export function pctOfFullDayTarget(
276	  sold: number,
277	  dailyTarget: number | null | undefined,
278	): number | null {
279	  if (dailyTarget == null || dailyTarget <= 0) return null;
280	  return (sold / dailyTarget) * 100;
281	}
282	
283	// ─────────────────────────────────────────────────────────────────────────────
284	// Deltas comparativos (genéricos: vendas, perdas, compras — qualquer base)
285	// ─────────────────────────────────────────────────────────────────────────────
286	
287	/**
288	 * Delta % de `current` vs uma base de referência qualquer (ontem, semana
289	 * passada, período anterior do filtro…). Retorna null quando a base é
290	 * ausente ou não positiva — sem base honesta, sem número inventado.
291	 */
292	export function relativeDelta(
293	  current: number,
294	  base: number | null | undefined,
295	): number | null {
296	  if (base == null || base <= 0) return null;
297	  return ((current - base) / base) * 100;
298	}
299	
300	/**
301	 * Delta % vs MESMO DIA da semana anterior — caso particular de
302	 * {@link relativeDelta}, mantido pelo nome de domínio (comparativo
303	 * SECUNDÁRIO desde a v3; o principal é vs dia anterior).
304	 */
305	export function weekOverWeekDelta(
306	  current: number,
307	  lastWeek: number | null | undefined,
308	): number | null {
309	  return relativeDelta(current, lastWeek);
310	}
311	
312	/**
313	 * Base PRÓ-RATEADA de QUALQUER dia de referência para deltas do canal LIVE:
314	 * `referenceDayTotal × businessDayFraction(now)` — o delta resultante compara
315	 * hoje (dia parcial) vs o MESMO PONTO do dia de referência (ontem, semana
316	 * passada…), assumindo distribuição intra-dia linear na janela (mesma fração
317	 * usada no pró-rata da meta, por consistência).
318	 *
319	 * Comparar dia parcial com dia completo inflava a queda de manhã.
320	 * Canal defasado (dia completo vs dia completo) NÃO usa esta função.
321	 *
322	 * Retorna null quando a base é ausente/não positiva ou antes da abertura
323	 * (fração 0 — não há ponto de comparação honesto).
324	 */
325	export function proRataDayBase(
326	  referenceDayTotal: number | null | undefined,
327	  now: Date,
328	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
329	): number | null {
330	  if (referenceDayTotal == null || referenceDayTotal <= 0) return null;
331	  const fraction = businessDayFraction(now, hours);
332	  if (fraction <= 0) return null;
333	  return referenceDayTotal * fraction;
334	}
335	
336	/**
337	 * Alias histórico de {@link proRataDayBase} com o dia de referência fixado
338	 * em "mesmo dia da semana passada" (nome da v1/v2 — mantido para não quebrar
339	 * a API existente).
340	 */
341	export function proRataLastWeekBase(
342	  lastWeek: number | null | undefined,
343	  now: Date,
344	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
345	): number | null {
346	  return proRataDayBase(lastWeek, now, hours);
347	}
348	
349	// ─────────────────────────────────────────────────────────────────────────────
350	// RAG da loja
351	// ─────────────────────────────────────────────────────────────────────────────
352	
353	/** Entrada da classificação RAG de uma unidade. */
354	export interface StoreRagInput {
355	  /** Itens zerados em alerta (quantidade ≤ 0 com mínimo definido). */
356	  stockOutCount: number;
357	  /** Itens abaixo do mínimo (quantidade entre 0 exclusivo e o mínimo). */
358	  stockLowCount: number;
359	  /** % da meta pró-rata (apenas canal live; null = não avaliar). */
360	  pctMetaProRata: number | null;
361	  /** true quando a unidade tem venda ao vivo (canal Degust). */
362	  isLiveChannel: boolean;
363	  /** Última movimentação de estoque (ISO/Date), ou null se nenhuma hoje. */
364	  lastMovementAt: Date | string | null;
365	  /** Instante da avaliação. */
366	  now: Date;
367	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
368	  hours?: TvBusinessHours;
369	  /** Threshold de horas sem movimentação (default lojas 3h; fábrica 2h). */
370	  noMovementThresholdHours?: number;
371	}
372	
373	/**
374	 * Horas sem movimentação consideradas DENTRO da janela de funcionamento.
375	 *
376	 * - Fora da janela (antes de abrir / depois de fechar) retorna null —
377	 *   não faz sentido alertar madrugada sem bipagem.
378	 * - A referência é clampada ao início da janela de hoje: se a última
379	 *   movimentação foi ontem, o "relógio" só começa a contar na abertura.
380	 */
381	export function hoursWithoutMovementInWindow(
382	  lastMovementAt: Date | string | null,
383	  now: Date,
384	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
385	): number | null {
386	  const fraction = businessDayFraction(now, hours);
387	  if (fraction <= 0 || fraction >= 1) return null;
388	  const windowStart = new Date(now);
389	  windowStart.setHours(hours.start, 0, 0, 0);
390	  const last = lastMovementAt
391	    ? new Date(lastMovementAt).getTime()
392	    : Number.NEGATIVE_INFINITY;
393	  const ref = Math.max(last, windowStart.getTime());
394	  return (now.getTime() - ref) / 3_600_000;
395	}
396	
397	/**
398	 * Classificação RAG de uma unidade (management-by-exception).
399	 *
400	 * Regras (design.md §1.6, ordem de precedência):
401	 * - VERMELHO: SOMENTE ruptura — item zerado em alerta (`stockOutCount > 0`).
402	 *   Venda fraca NUNCA derruba o card pra vermelho (era falso-positivo de
403	 *   manhã, quando o pró-rata ainda é instável).
404	 * - ÂMBAR: itens abaixo do mínimo (`stockLowCount > 0`) OU unidade sem
405	 *   movimentação há mais que o threshold dentro da janela OU venda live com
406	 *   ratio pró-rata abaixo de {@link LIVE_SALES_AMBER_THRESHOLD_PCT}% —
407	 *   esta última SOMENTE a partir de {@link LIVE_SALES_AMBER_FROM_HOUR}h,
408	 *   em canal live e com meta cadastrada (pct != null).
409	 * - OK: nenhum desvio — tela calma, sem cor.
410	 */
411	export function classifyStoreRag(input: StoreRagInput): {
412	  status: TvRagStatus;
413	  reasons: string[];
414	} {
415	  const hours = input.hours ?? TV_BUSINESS_HOURS;
416	  const noMovementThreshold =
417	    input.noMovementThresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
418	  const reasons: string[] = [];
419	
420	  // ── Vermelho: só ruptura (item zerado em alerta) ──
421	  if (input.stockOutCount > 0) {
422	    reasons.push(
423	      `${input.stockOutCount} ${input.stockOutCount === 1 ? 'item zerado' : 'itens zerados'} em alerta`,
424	    );
425	    return { status: 'red', reasons };
426	  }
427	
428	  // ── Âmbar ──
429	  if (input.stockLowCount > 0) {
430	    reasons.push(
431	      `${input.stockLowCount} ${input.stockLowCount === 1 ? 'item abaixo' : 'itens abaixo'} do mínimo`,
432	    );
433	  }
434	  const gapHours = hoursWithoutMovementInWindow(
435	    input.lastMovementAt,
436	    input.now,
437	    hours,
438	  );
439	  if (gapHours !== null && gapHours > noMovementThreshold) {
440	    reasons.push(`sem movimentação há ${Math.floor(gapHours)}h`);
441	  }
442	  if (
443	    input.isLiveChannel &&
444	    input.pctMetaProRata !== null &&
445	    input.pctMetaProRata < LIVE_SALES_AMBER_THRESHOLD_PCT &&
446	    input.now.getHours() >= LIVE_SALES_AMBER_FROM_HOUR
447	  ) {
448	    reasons.push(
449	      `venda ao vivo em ${Math.round(input.pctMetaProRata)}% do esperado pró-rata`,
450	    );
451	  }
452	  if (reasons.length > 0) return { status: 'amber', reasons };
453	
454	  return { status: 'ok', reasons: [] };
455	}
456	
457	/** Entrada de {@link buildNoMovementException}. */
458	export interface NoMovementExceptionInput {
459	  lojaId: number;
460	  lojaNome: string;
461	  /** Timestamp da última movimentação (ISO/Date), ou null se nenhuma hoje. */
462	  lastMovementAt: Date | string | null;
463	  now: Date;
464	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
465	  hours?: TvBusinessHours;
466	  /** Threshold em horas (default lojas 3h; fábrica 2h). */
467	  thresholdHours?: number;
468	}
469	
470	/**
471	 * Exceção "sem movimentação" derivada DIRETO do dado estruturado (timestamp
472	 * da última bipagem + janela), nunca por parsing de string de ragReasons —
473	 * por isso INDEPENDE da cor do card (aparece mesmo com card vermelho) e
474	 * cobre também a fábrica (janela/threshold próprios via parâmetros).
475	 * Retorna null quando não há gap acima do threshold dentro da janela.
476	 */
477	export function buildNoMovementException(
478	  input: NoMovementExceptionInput,
479	): TvException | null {
480	  const threshold = input.thresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
481	  const gap = hoursWithoutMovementInWindow(
482	    input.lastMovementAt,
483	    input.now,
484	    input.hours ?? TV_BUSINESS_HOURS,
485	  );
486	  if (gap === null || gap <= threshold) return null;
487	  return {
488	    id: `no-movement:${input.lojaId}`,
489	    kind: 'no-movement',
490	    severity: 'amber',
491	    lojaId: input.lojaId,
492	    lojaNome: input.lojaNome,
493	    message: `${input.lojaNome} sem movimentação há ${Math.floor(gap)}h em horário comercial`,
494	  };
495	}
496	
497	// ─────────────────────────────────────────────────────────────────────────────
498	// Formatação compacta de moeda (tipografia de TV: "R$ 12,4k")
499	// ─────────────────────────────────────────────────────────────────────────────
500	
501	function trimOneDecimal(v: number): string {
502	  const rounded = Math.round(v * 10) / 10;
503	  return rounded.toLocaleString('pt-BR', {
504	    minimumFractionDigits: 0,
505	    maximumFractionDigits: 1,
506	  });
507	}
508	
509	/**
510	 * Formata um valor em BRL compacto para leitura a 3-5 metros:
511	 * 950 → "R$ 950" · 12.400 → "R$ 12,4k" · 1.250.000 → "R$ 1,3M".
512	 * Valores negativos preservam o sinal ("-R$ 1,2k").
513	 */
514	export function formatCompactBRL(value: number): string {
515	  const sign = value < 0 ? '-' : '';
516	  const abs = Math.abs(value);
517	  // Bump pra M quando o arredondamento em k chegaria a 1000k
518	  if (abs >= 1_000_000 || (abs >= 1_000 && Math.round(abs / 100) >= 10_000)) {
519	    return `${sign}R$ ${trimOneDecimal(abs / 1_000_000)}M`;
520	  }
521	  if (abs >= 1_000) {
522	    return `${sign}R$ ${trimOneDecimal(abs / 1_000)}k`;
523	  }
524	  return `${sign}R$ ${Math.round(abs).toLocaleString('pt-BR')}`;
525	}
