588	
589	const SEVERITY_ORDER: Record<string, number> = { red: 0, amber: 1 };
590	// design.md §6.1: rupturas → abaixo-do-mínimo → sem-bipagem → stale
591	const KIND_ORDER: Record<string, number> = {
592	  'stock-out': 0,
593	  'stock-low': 1,
594	  'no-movement': 2,
595	  'stale-data': 3,
596	};
597	
598	/**
599	 * Ordena exceções por severidade (vermelho antes de âmbar), depois por tipo
600	 * (falta total, abaixo do mínimo, sem movimentação, dado stale — nesta ordem,
601	 * design.md §6.1) e por mensagem (estável), limitando a `limit` linhas com
602	 * contagem do excedente.
603	 */
604	export function sortAndLimitExceptions(
605	  exceptions: TvException[],
606	  limit: number = TV_EXCEPTIONS_LIMIT,
607	): TvExceptionsResult {
608	  const sorted = [...exceptions].sort((a, b) => {
609	    const sev = (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9);
610	    if (sev !== 0) return sev;
611	    const kind = (KIND_ORDER[a.kind] ?? 9) - (KIND_ORDER[b.kind] ?? 9);
612	    if (kind !== 0) return kind;
613	    return a.message.localeCompare(b.message, 'pt-BR');
614	  });
615	  return {
616	    items: sorted.slice(0, limit),
617	    overflowCount: Math.max(0, sorted.length - limit),
618	    totalCount: sorted.length,
619	  };
620	}
