757	/**
758	 * Corrige o `loja_id` das linhas de flash-vendas.
759	 *
760	 * LANDMINE conhecida: a edge function `degust-pos-financial` (deployada)
761	 * só mapeia os códigos Degust 1→4 e 2→5; códigos não mapeados passam CRUS
762	 * (ex.: BSB Shopping = código Degust 3 chega como `loja_id: 3`, colidindo
763	 * com Asa Norte). Aqui remapeamos usando a tabela `degust_stores`
764	 * (degust_loja_codigo → loja_id), que é a fonte de verdade em runtime.
765	 *
766	 * - Linha cujo loja_id já é uma loja Degust conhecida → mantém.
767	 * - Linha cujo loja_id corresponde a um código Degust → remapeia.
768	 * - Caso contrário → descarta (não corromper outra loja).
769	 */
770	export function remapFlashLojaIds(
771	  rows: FlashRow[],
772	  degustCodeToLoja: ReadonlyMap<number, number>,
773	  knownDegustLojaIds: ReadonlySet<number>,
774	): FlashRow[] {
775	  const out: FlashRow[] = [];
776	  for (const row of rows) {
777	    if (knownDegustLojaIds.has(row.loja_id)) {
778	      out.push(row);
779	      continue;
780	    }
781	    const mapped = degustCodeToLoja.get(row.loja_id);
782	    if (mapped != null) {
783	      out.push({ ...row, loja_id: mapped });
784	    }
785	    // não mapeável → descartado de propósito (ver TSDoc)
786	  }
787	  return out;
788	}
