827	/**
828	 * Converte os itens de alerta de uma unidade em estoque crítico NOMEADO,
829	 * ordenado por severidade: zerados (⛔) primeiro, depois abaixo do mínimo
830	 * (⚠) por % FALTANTE decrescente ((minima − quantidade) / minima); empate
831	 * por nome (estável). Dentro dos zerados, quantidade mais negativa primeiro
832	 * (mesma fração). A coluna exibe os {@link TV_CRITICAL_TOP_N} primeiros;
833	 * o drill-down, a lista completa.
834	 */
835	export function sortCriticalItems(items: TvStockAlertItem[]): TvCriticalItem[] {
836	  const missingFraction = (c: TvCriticalItem): number =>
837	    c.minima > 0 ? (c.minima - c.quantidade) / c.minima : 0;
838	  return items
839	    .map<TvCriticalItem>((i) => ({
840	      nome: i.produtoNome,
841	      quantidade: i.quantidade,
842	      minima: i.quantidadeMinima,
843	      severity: i.zerado ? 'zerado' : 'abaixo-minimo',
844	    }))
845	    .sort((a, b) => {
846	      if (a.severity !== b.severity) return a.severity === 'zerado' ? -1 : 1;
847	      const diff = missingFraction(b) - missingFraction(a);
848	      if (diff !== 0) return diff;
849	      return a.nome.localeCompare(b.nome, 'pt-BR');
850	    });
851	}
