971	// ─────────────────────────────────────────────────────────────────────────────
972	// Paginação PostgREST (loop genérico com fetcher injetado — sem I/O próprio)
973	// ─────────────────────────────────────────────────────────────────────────────
974	
975	/** Página de resultado mínima consumida por {@link fetchAllPages}. */
976	export interface TvPageResult<T> {
977	  data: T[] | null;
978	  error: { message: string } | null;
979	}
980	
981	/**
982	 * Busca TODAS as linhas paginando com `.range()`: o PostgREST corta qualquer
983	 * resposta em 1000 linhas mesmo com `.limit()` maior — truncamento SILENCIOSO
984	 * (mesmo padrão de `features/producao/hooks/useProductionForecast`).
985	 *
986	 * Loop até a página vir menor que `pageSize`. O fetcher é injetado (esta
987	 * função não faz I/O próprio — testável com mock) e DEVE aplicar ordenação
988	 * estável (`.order` em coluna única, ex.: `id`) para as páginas não se
989	 * sobreporem entre requests.
990	 */
991	export async function fetchAllPages<T>(
992	  fetchPage: (from: number, to: number) => PromiseLike<TvPageResult<T>>,
993	  pageSize = 1000,
994	): Promise<T[]> {
995	  const all: T[] = [];
996	  let offset = 0;
997	  for (;;) {
998	    const { data, error } = await fetchPage(offset, offset + pageSize - 1);
999	    if (error) throw error;
1000	    const rows = data ?? [];
1001	    all.push(...rows);
1002	    if (rows.length < pageSize) return all;
1003	    offset += pageSize;
1004	  }
1005	}
