391	export async function fetchStockAlerts(): Promise<StockRow[]> {
392	  // PostgREST não compara coluna×coluna (quantidade_atual < quantidade_minima):
393	  // buscamos as linhas com mínimo definido e filtramos no cliente (~1.4k linhas
