484	// ─────────────────────────────────────────────────────────────────────────────
485	// Perdas no período do filtro global (tabela `perdas`)
486	// ─────────────────────────────────────────────────────────────────────────────
487	
488	/** Par período corrente + período anterior equivalente (comparativo). */
489	export interface PeriodedAggregates<T> {
490	  current: T;
491	  previous: T;
492	}
493	
494	async function loadPerdasRange(range: TvDateRange): Promise<PerdasByLoja> {
495	  const bounds = rangeToLocalDayBounds(range);
496	  // Paginado: um mês de perdas pode passar de 1000 linhas (corte silencioso
497	  // do PostgREST). `data_identificacao` é timestamptz → bounds de dia local.
498	  const rows = await fetchAllPages((from, to) =>
499	    supabase
500	      .from('perdas')
501	      .select('loja_id, valor_estimado')
502	      .gte('data_identificacao', bounds.startIso)
503	      .lt('data_identificacao', bounds.endExclusiveIso)
504	      .order('id')
505	      .range(from, to),
506	  );
507	  return aggregatePerdas(rows);
508	}
509	
510	async function fetchPerdasAggregates(
511	  period: TvPeriod,
512	): Promise<PeriodedAggregates<PerdasByLoja>> {
513	  const now = new Date();
514	  const [current, previous] = await Promise.all([
515	    loadPerdasRange(periodRange(period, now)),
516	    loadPerdasRange(previousPeriodRange(period, now)),
517	  ]);
518	  return { current, previous };
519	}
