544	async function fetchComprasAggregates(
545	  period: TvPeriod,
546	): Promise<PeriodedAggregates<ComprasByLoja>> {
547	  const now = new Date();
548	  const [current, previous] = await Promise.all([
549	    loadComprasRange(periodRange(period, now)),
550	    loadComprasRange(previousPeriodRange(period, now)),
551	  ]);
552	  return { current, previous };
553	}
