559	async function fetchFactoryProduction(): Promise<TvFactoryProduction | null> {
560	  const today = toIsoDateLocal(new Date());
561	
562	  const loadDay = async (date: string) => {
563	    const { data, error } = await supabase
564	      .from('daily_production')
565	      .select('quantity')
566	      .is('loja_id', null)
567	      .eq('date', date)
568	      .limit(2000);
569	    if (error) throw error;
570	    return data ?? [];
571	  };
572	
573	  let refDate = today;
574	  let rows = await loadDay(today);
575	  if (rows.length === 0) {
576	    // Sem produção registrada hoje → mostra o último dia disponível
577	    const { data: latest, error } = await supabase
578	      .from('daily_production')
579	      .select('date')
580	      .is('loja_id', null)
581	      .lte('date', today)
582	      .order('date', { ascending: false })
583	      .limit(1);
584	    if (error) throw error;
585	    const lastDate = latest?.[0]?.date;
586	    if (!lastDate) return null;
587	    refDate = lastDate;
588	    rows = await loadDay(lastDate);
589	  }
590	
591	  return {
592	    dataReferencia: refDate,
593	    itens: rows.length,
594	    totalUnidades: rows.reduce((s, r) => s + (r.quantity ?? 0), 0),
595	  };
596	}
