599	// Top produtos do dia da rede (degust_vendas_diarias, SOMENTE hoje)
600	// ─────────────────────────────────────────────────────────────────────────────
601	
602	async function fetchTopProducts(ctx: TvContext): Promise<TvTopProduct[]> {
603	  const ids = [...ctx.degustLojaIds];
604	  if (ids.length === 0) return [];
605	  // O card é rotulado "TOP 5 PRODUTOS · HOJE": filtra `data` = hoje no fuso
606	  // LOCAL (mesmo `toIsoDateLocal` usado no resto do hook). Sem vendas hoje →
607	  // lista vazia (a UI mostra "aguardando vendas do dia"); nunca mostrar
608	  // ontem com rótulo de hoje.
609	  const today = toIsoDateLocal(new Date());
610	  const data = await fetchAllPages((from, to) =>
611	    supabase
612	      .from('degust_vendas_diarias')
613	      .select('degust_nome, quantidade, valor_total')
614	      .eq('data', today)
615	      .in('loja_id', ids)
616	      .order('id')
617	      .range(from, to),
618	  );
619	  return topProductsFromDaily(data, 5);
620	}
