626	/** Retorno do {@link useTvDashboardData}. */
627	export interface TvDashboardData {
628	  network: TvNetworkSummary | null;
629	  stores: TvStoreData[];
630	  factory: TvFactoryData | null;
631	  exceptions: TvExceptionsResult;
