678	/**
679	 * Hook principal do painel TV. Paraleliza todas as fontes e devolve o
680	 * snapshot consolidado (`network`, `stores`, `factory`, `exceptions`,
681	 * `topProducts`, `freshness`). Vendas live re-buscam a cada 60s; o resto a
682	 * cada 5min (com invalidação antecipada via {@link useTvRealtime}).
683	 *
684	 * @param period - Filtro global Hoje/Semana/Mês — muda perdas, compras e
685	 *   seus comparativos. Vendas dos cards são SEMPRE de hoje (+ % vs ontem).
686	 */
687	export function useTvDashboardData(period: TvPeriod = 'today'): TvDashboardData {
688	  // "now" que AVANÇA (tick de minuto): staleness/RAG/pró-rata reclassificam
689	  // mesmo quando NENHUMA query devolve dado novo (outage total). Sem isso o
690	  // chip ficaria "✓ ao vivo" pra sempre com tudo fora do ar.
691	  const tick = useMinuteClock();
692	
693	  const ctxQuery = useQuery({
694	    queryKey: tvDashboardKeys.context(),
695	    queryFn: fetchTvContext,
696	    staleTime: TV_QUERY_INTERVALS.slowMs,
697	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
698	  });
699	  const ctx = ctxQuery.data;
700	
701	  const liveQuery = useQuery({
702	    queryKey: tvDashboardKeys.liveSales(),
703	    queryFn: () => {
704	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
705	      return fetchLiveSales(ctx);
706	    },
707	    enabled: !!ctx,
708	    refetchInterval: TV_QUERY_INTERVALS.liveMs,
709	    staleTime: 30_000,
710	  });
711	
712	  const laggedQuery = useQuery({
713	    queryKey: tvDashboardKeys.laggedSales(),
714	    queryFn: () => {
715	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
716	      return fetchLaggedSales(ctx);
717	    },
718	    enabled: !!ctx,
719	    staleTime: TV_QUERY_INTERVALS.slowMs,
720	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
721	  });
722	
723	  const referenceQuery = useQuery({
724	    queryKey: tvDashboardKeys.referenceSales(),
725	    queryFn: () => {
726	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
727	      return fetchDegustReference(ctx);
728	    },
729	    enabled: !!ctx,
730	    staleTime: TV_QUERY_INTERVALS.slowMs,
731	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
732	  });
733	
734	  const perdasQuery = useQuery({
735	    queryKey: tvDashboardKeys.perdas(period),
736	    queryFn: () => fetchPerdasAggregates(period),
737	    staleTime: TV_QUERY_INTERVALS.slowMs,
738	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
739	  });
740	
741	  const comprasQuery = useQuery({
742	    queryKey: tvDashboardKeys.compras(period),
743	    queryFn: () => fetchComprasAggregates(period),
744	    staleTime: TV_QUERY_INTERVALS.slowMs,
745	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
746	  });
747	
748	  const feedQuery = useQuery({
749	    queryKey: tvDashboardKeys.movementFeed(),
750	    queryFn: fetchMovementFeed,
751	    staleTime: TV_QUERY_INTERVALS.slowMs,
752	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
753	  });
754	
755	  const metasQuery = useQuery({
756	    queryKey: tvDashboardKeys.metas(),
757	    queryFn: fetchMetas,
758	    staleTime: TV_QUERY_INTERVALS.slowMs,
759	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
760	  });
761	
762	  const stockQuery = useQuery({
763	    queryKey: tvDashboardKeys.stock(),
764	    queryFn: fetchStockAlerts,
765	    staleTime: TV_QUERY_INTERVALS.slowMs,
766	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
767	  });
768	
769	  const movementsQuery = useQuery({
770	    queryKey: tvDashboardKeys.movements(),
771	    queryFn: fetchMovementsToday,
772	    staleTime: TV_QUERY_INTERVALS.slowMs,
773	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
774	  });
775	
776	  const factoryQuery = useQuery({
777	    queryKey: tvDashboardKeys.factoryProduction(),
778	    queryFn: fetchFactoryProduction,
779	    staleTime: TV_QUERY_INTERVALS.slowMs,
780	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
781	  });
782	
783	  const topQuery = useQuery({
784	    queryKey: tvDashboardKeys.topProducts(),
785	    queryFn: () => {
786	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
787	      return fetchTopProducts(ctx);
788	    },
789	    enabled: !!ctx,
790	    staleTime: TV_QUERY_INTERVALS.slowMs,
791	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
792	  });
793	
794	  return useMemo<TvDashboardData>(() => {
795	    const now = tick;
796	    const todayIso = toIsoDateLocal(now);
797	    const range = periodRange(period, now);
798	    const previousRange = previousPeriodRange(period, now);
799	
800	    const stockDetail: Map<number, StockDetail> = buildStockSummary(
801	      stockQuery.data ?? [],
802	    );
803	    const movements = movementsQuery.data ?? new Map<number, MovementAggregate>();
804	    const feedByLoja = feedQuery.data ?? new Map<number, TvRecentMove[]>();
805	    const flashByLoja = new Map<number, FlashRow>(
806	      (liveQuery.data ?? []).map((f) => [f.loja_id, f]),
807	    );
808	    const laggedByLoja = new Map<number, LaggedSales>(
809	      (laggedQuery.data ?? []).map((l) => [l.lojaId, l]),
810	    );
811	    const lastWeekByLoja = referenceQuery.data?.lastWeek ?? new Map<number, number>();
812	    const yesterdayByLoja = referenceQuery.data?.yesterday ?? new Map<number, number>();
813	    const perdasAgg = perdasQuery.data;
814	    const comprasAgg = comprasQuery.data;
815	    const lojaNomeById = new Map<number, string>(
816	      (ctx?.lojas ?? []).map((l) => [l.id, l.nome]),
817	    );
818	
819	    // ── Cards de loja ──
820	    const stores: TvStoreData[] = (ctx?.lojas ?? [])
821	      .filter((l) => !isFactoryTipo(l.tipo))
822	      .map((loja) => {
823	        const channel: TvSalesChannel = ctx?.degustLojaIds.has(loja.id)
824	          ? 'degust-live'
825	          : 'linx-lagged';
826	        const stock = stockDetail.get(loja.id);
827	        const movement = movements.get(loja.id) ?? EMPTY_MOVEMENT;
828	
829	        let vendas: TvSalesSnapshot | null = null;
830	        let metaDia: number | null = null;
831	        let pctMeta: number | null = null;
832	        let deltaSemana: number | null = null;
833	        let deltaOntem: number | null = null;
834	
835	        if (channel === 'degust-live') {
836	          const flash = flashByLoja.get(loja.id);
837	          if (flash) {
838	            vendas = {
839	              valor: flash.total_vendas,
840	              cupons: flash.total_cupons,
841	              ticketMedio: flash.ticket_medio,
842	              dataReferencia: todayIso,
843	              isLive: true,
844	              caixaAberto: flash.caixa_aberto,
845	              atualizadoEm: flash.ultima_atualizacao,
846	            };
847	            metaDia = metaFor(metasQuery.data, loja.id, now);
848	            pctMeta = pctOfProRataTarget(flash.total_vendas, metaDia, now);
849	            // Deltas live = "vs MESMO PONTO do dia de referência": a base
850	            // (ontem = PRINCIPAL v3; semana passada = secundário) é
851	            // pró-rateada pela fração da janela já decorrida (mesma fração
852	            // do pró-rata da meta). Comparar hoje PARCIAL com dia COMPLETO
853	            // inflava a queda de manhã.
854	            deltaOntem = relativeDelta(
855	              flash.total_vendas,
856	              proRataDayBase(yesterdayByLoja.get(loja.id) ?? null, now),
857	            );
858	            deltaSemana = weekOverWeekDelta(
859	              flash.total_vendas,
860	              proRataDayBase(lastWeekByLoja.get(loja.id) ?? null, now),
861	            );
862	          }
863	        } else {
864	          const lagged = laggedByLoja.get(loja.id);
865	          if (lagged) {
866	            vendas = {
867	              valor: lagged.valor,
868	              cupons: null,
869	              ticketMedio: null,
870	              dataReferencia: lagged.dataReferencia,
871	              isLive: false,
872	              caixaAberto: null,
873	              atualizadoEm: null,
874	            };
875	            // Meta do dia da semana do DIA DE REFERÊNCIA (já encerrado → sem pró-rata)
876	            const refDate = parseIsoDateLocal(lagged.dataReferencia);
877	            metaDia = metaFor(metasQuery.data, loja.id, refDate);
878	            pctMeta = pctOfFullDayTarget(lagged.valor, metaDia);
879	            // Canal defasado: dia COMPLETO vs dia COMPLETO — sem pró-rata.
880	            // Principal v3 = vs dia ANTERIOR ao de referência.
881	            deltaOntem = relativeDelta(lagged.valor, lagged.valorDiaAnterior);
882	            deltaSemana = weekOverWeekDelta(
883	              lagged.valor,
884	              lagged.valorSemanaAnterior,
885	            );
886	          }
887	        }
888	
889	        const rag = classifyStoreRag({
890	          stockOutCount: stock?.zerados ?? 0,
891	          stockLowCount: stock?.abaixoMinimo ?? 0,
892	          pctMetaProRata: channel === 'degust-live' ? pctMeta : null,
893	          isLiveChannel: channel === 'degust-live',
894	          lastMovementAt: movement.ultimaBipagem,
895	          now,
896	        });
897	
898	        return {
899	          lojaId: loja.id,
900	          nome: loja.nome,
901	          channel,
902	          vendas,
903	          metaDia,
904	          pctMeta,
905	          deltaSemana,
906	          deltaOntem,
907	          estoque: {
908	            zerados: stock?.zerados ?? 0,
909	            abaixoMinimo: stock?.abaixoMinimo ?? 0,
910	          },
911	          movimentacao: movement,
912	          perdas: perdasSummaryFor(perdasAgg, loja.id),
913	          compras: comprasSummaryFor(comprasAgg, loja.id),
914	          criticalItems: sortCriticalItems(stock?.itens ?? []),
915	          recentMoves: feedByLoja.get(loja.id) ?? [],
916	          rag: rag.status,
917	          ragReasons: rag.reasons,
918	        };
919	      });
920	
921	    // ── Card da fábrica ──
922	    let factory: TvFactoryData | null = null;
923	    if (ctx?.factoryLojaId != null) {
924	      const fid = ctx.factoryLojaId;
925	      const stock = stockDetail.get(fid);
926	      const movement = movements.get(fid) ?? EMPTY_MOVEMENT;
927	      const rag = classifyStoreRag({
928	        stockOutCount: stock?.zerados ?? 0,
929	        stockLowCount: stock?.abaixoMinimo ?? 0,
930	        pctMetaProRata: null,
931	        isLiveChannel: false,
932	        lastMovementAt: movement.ultimaBipagem,
933	        now,
934	        // Janela de PRODUÇÃO (06–18h, threshold 2h) — mesma do card visual
935	        hours: TV_FACTORY_HOURS,
936	        noMovementThresholdHours: FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
937	      });
938	      factory = {
939	        lojaId: fid,
940	        nome: lojaNomeById.get(fid) ?? 'Fábrica',
941	        producao: factoryQuery.data ?? null,
942	        expedicoes: movement,
943	        estoque: {
944	          zerados: stock?.zerados ?? 0,
945	          abaixoMinimo: stock?.abaixoMinimo ?? 0,
946	        },
947	        perdas: perdasSummaryFor(perdasAgg, fid),
948	        compras: comprasSummaryFor(comprasAgg, fid),
949	        criticalItems: sortCriticalItems(stock?.itens ?? []),
950	        recentMoves: feedByLoja.get(fid) ?? [],
951	        rag: rag.status,
952	        ragReasons: rag.reasons,
953	      };
954	    }
955	
956	    // ── Freshness ──
957	    // Classificada com `now` do tick de minuto: quando dataUpdatedAt para de
958	    // avançar (outage), a idade cresce e o chip escala pra âmbar mesmo sem
959	    // nenhum dado novo chegar. Os timestamps CRUS ficam expostos no retorno.
960	    const freshness: TvFreshness = buildFreshness(
961	      liveQuery.dataUpdatedAt,
962	      stockQuery.dataUpdatedAt,
963	      TV_QUERY_INTERVALS,
964	      now,
965	    );
966	
967	    // ── Exceções (vermelho > âmbar, máx 7 + excedente) ──
968	    const allExceptions: TvException[] = buildStockExceptions(
969	      stockDetail,
970	      lojaNomeById,
971	    );
972	    // "Sem movimentação" derivada do DADO estruturado (última bipagem ×
973	    // janela), nunca por parsing de ragReasons — independe da cor do card
974	    // (aparece mesmo com card vermelho) e cobre também a fábrica.
975	    for (const store of stores) {
976	      const noMovement = buildNoMovementException({
977	        lojaId: store.lojaId,
978	        lojaNome: store.nome,
979	        lastMovementAt: store.movimentacao.ultimaBipagem,
980	        now,
981	      });
982	      if (noMovement) allExceptions.push(noMovement);
983	    }
984	    if (factory) {
985	      const noMovement = buildNoMovementException({
986	        lojaId: factory.lojaId,
987	        lojaNome: factory.nome,
988	        lastMovementAt: factory.expedicoes.ultimaBipagem,
989	        now,
990	        hours: TV_FACTORY_HOURS,
991	        thresholdHours: FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
992	      });
993	      if (noMovement) allExceptions.push(noMovement);
994	    }
995	    if (freshness.vendasLive.level !== 'fresh' && (ctx?.degustLojaIds.size ?? 0) > 0) {
996	      const liveUpdatedAt = freshness.vendasLive.updatedAt;
997	      allExceptions.push({
998	        id: 'stale-data:vendas-live',
999	        kind: 'stale-data',
1000	        severity: 'amber',
1001	        lojaId: null,
1002	        lojaNome: null,
1003	        message: liveUpdatedAt
1004	          ? `Venda live sem atualização desde ${new Date(liveUpdatedAt).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`
1005	          : 'Venda live ainda não carregou',
1006	      });
1007	    }
1008	    const exceptions = sortAndLimitExceptions(allExceptions);
1009	
1010	    // ── Hero (rede) ──
1011	    // Soma apenas lojas cujo dado é de HOJE (live) — não misturar dias.
1012	    const liveStores = stores.filter(
1013	      (s) => s.vendas?.isLive && s.vendas.dataReferencia === todayIso,
1014	    );
1015	    const vendasHoje = liveStores.reduce((s, st) => s + (st.vendas?.valor ?? 0), 0);
1016	    const metasHoje = liveStores
1017	      .map((s) => s.metaDia)
1018	      .filter((m): m is number => m != null && m > 0);
1019	    const metaDia = metasHoje.length > 0 ? metasHoje.reduce((a, b) => a + b, 0) : null;
1020	    const lastWeekTotal = liveStores.reduce(
1021	      (s, st) => s + (lastWeekByLoja.get(st.lojaId) ?? 0),
1022	      0,
1023	    );
1024	    const yesterdayTotal = liveStores.reduce(
1025	      (s, st) => s + (yesterdayByLoja.get(st.lojaId) ?? 0),
1026	      0,
1027	    );
1028	    const network: TvNetworkSummary | null = ctx
1029	      ? {
1030	          vendasHoje,
1031	          metaDia,
1032	          pctMetaProRata: pctOfProRataTarget(vendasHoje, metaDia, now),
1033	          // Mesmo critério do card live: deltas "vs mesmo ponto do dia de
1034	          // referência" (base pró-rateada pela fração da janela). Ontem é
1035	          // o PRINCIPAL (v3); semana passada segue como secundário.
1036	          deltaSemana: weekOverWeekDelta(
1037	            vendasHoje,
1038	            proRataDayBase(lastWeekTotal, now),
1039	          ),
1040	          deltaOntem: relativeDelta(
1041	            vendasHoje,
1042	            proRataDayBase(yesterdayTotal, now),
1043	          ),
1044	          // Totais da REDE: incluem linhas sem loja_id (não atribuíveis a
1045	          // nenhuma coluna — entram SOMENTE aqui).
1046	          perdas: {
1047	            valor: perdasAgg?.current.total.valor ?? 0,
1048	            itens: perdasAgg?.current.total.itens ?? 0,
1049	            deltaPct: relativeDelta(
1050	              perdasAgg?.current.total.valor ?? 0,
1051	              perdasAgg?.previous.total.valor ?? null,
1052	            ),
1053	          },
1054	          compras: {
1055	            valor: comprasAgg?.current.total ?? 0,
1056	            deltaPct: relativeDelta(
1057	              comprasAgg?.current.total ?? 0,
1058	              comprasAgg?.previous.total ?? null,
1059	            ),
1060	          },
1061	          alertasCriticos: allExceptions.filter((e) => e.severity === 'red').length,
1062	          lojasLive: liveStores.length,
1063	          lojasDefasadas: stores.filter((s) => s.channel === 'linx-lagged').length,
1064	        }
1065	      : null;
1066	
1067	    return {
1068	      network,
1069	      stores,
1070	      factory,
1071	      exceptions,
1072	      topProducts: topQuery.data ?? [],
1073	      freshness,
1074	      period,
1075	      range,
1076	      previousRange,
1077	      isLoading: ctxQuery.isLoading,
1078	      isError: ctxQuery.isError,
1079	    };
1080	  }, [
1081	    // `tick` é o que faz staleness/RAG avançarem em outage total (sem ele a
1082	    // classificação congelaria no último snapshot de dados).
1083	    tick,
1084	    period,
1085	    ctx,
1086	    ctxQuery.isLoading,
1087	    ctxQuery.isError,
1088	    liveQuery.data,
1089	    liveQuery.dataUpdatedAt,
1090	    laggedQuery.data,
1091	    referenceQuery.data,
1092	    metasQuery.data,
1093	    stockQuery.data,
1094	    stockQuery.dataUpdatedAt,
1095	    movementsQuery.data,
1096	    feedQuery.data,
1097	    perdasQuery.data,
1098	    comprasQuery.data,
1099	    factoryQuery.data,
1100	    topQuery.data,
1101	  ]);
1102	}
