1	/**
2	 * @module features/tv-dashboard/model/useTvStoreDetail
3	 *
4	 * Drill-down por loja (`/tv/loja/:id`) com filtro de data PRÓPRIO
5	 * (range custom de/até em dias locais):
6	 * - KPIs no range (vendas, perdas, compras, contagens de movimentações)
7	 *   com comparativo vs range ANTERIOR de mesma duração;
8	 * - listas: perdas detalhadas, NFs de compra, estoque crítico completo,
9	 *   feed de movimentações (até {@link TV_DETAIL_FEED_LIMIT}, mais recente 1º).
10	 *
11	 * Compartilha cache com o painel: contexto (lojas/canais) e estoque crítico
12	 * usam as MESMAS query keys do `useTvDashboardData`.
13	 *
14	 * Decisões herdadas do painel:
15	 * - vendas: Degust → `degust_vendas_diarias`; demais → `historico_vendas`
16	 *   (fábrica não vende → 0);
17	 * - compras: campo canônico `data_nota`, status válido ≠ erro, sem
18	 *   transferências "Momma Doces"; NFs com loja_id NULL nunca aparecem aqui
19	 *   (entram só no total da rede do hero);
20	 * - agregados potencialmente acima de 1000 linhas paginam via `fetchAllPages`.
21	 */
22	
23	import { useMemo } from 'react';
24	import { useQuery } from '@tanstack/react-query';
25	import { supabase } from '@/integrations/supabase/client';
26	import type {
27	  TvComprasSummary,
28	  TvCriticalItem,
29	  TvDateRange,
30	  TvNotaFiscalDetail,
31	  TvPerdaDetail,
32	  TvPerdasSummary,
33	  TvRecentMove,
34	  TvSalesChannel,
35	} from './types';
36	import {
37	  TV_DETAIL_FEED_LIMIT,
38	  aggregateMovements,
39	  aggregatePerdas,
40	  buildStockSummary,
41	  fetchAllPages,
42	  mapFeedRow,
43	  previousRangeSameDuration,
44	  rangeToLocalDayBounds,
45	  relativeDelta,
46	  sortCriticalItems,
47	} from './tvMath';
48	import {
49	  NF_COUNTED_STATUSES,
50	  NF_TRANSFER_SUPPLIER_PATTERN,
51	  TV_QUERY_INTERVALS,
52	  fetchStockAlerts,
53	  fetchTvContext,
54	  tvDashboardKeys,
55	  type TvContext,
56	} from './useTvDashboardData';
57	
58	// ─────────────────────────────────────────────────────────────────────────────
59	// Fetch consolidado do detalhe (1 queryFn, sub-fetches em paralelo)
60	// ─────────────────────────────────────────────────────────────────────────────
61	
62	interface MovementCounts {
63	  entradas: number;
64	  saidas: number;
65	}
66	
67	interface StoreDetailPayload {
68	  vendas: { valor: number; previous: number };
69	  perdas: { valor: number; itens: number; previousValor: number };
70	  compras: { valor: number; previousValor: number };
71	  movimentos: { current: MovementCounts; previous: MovementCounts };
72	  perdasList: TvPerdaDetail[];
73	  notasList: TvNotaFiscalDetail[];
74	  feed: TvRecentMove[];
75	}
76	
77	async function loadVendasRange(
78	  isDegust: boolean,
79	  lojaId: number,
80	  range: TvDateRange,
81	): Promise<number> {
82	  // Degust = degust_vendas_diarias (linha-por-produto/dia: um mês pode
83	  // passar de 1000 linhas → paginar); Linx = historico_vendas (idem).
84	  // Dois branches explícitos para o client tipado do Supabase (union de
85	  // nome de tabela degradaria a inferência).
86	  const rows = isDegust
87	    ? await fetchAllPages((from, to) =>
88	        supabase
89	          .from('degust_vendas_diarias')
90	          .select('valor_total')
91	          .eq('loja_id', lojaId)
92	          .gte('data', range.from)
93	          .lte('data', range.to)
94	          .order('id')
95	          .range(from, to),
96	      )
97	    : await fetchAllPages((from, to) =>
98	        supabase
99	          .from('historico_vendas')
100	          .select('valor_total')
101	          .eq('loja_id', lojaId)
102	          .gte('data', range.from)
103	          .lte('data', range.to)
104	          .order('id')
105	          .range(from, to),
106	      );
107	  return rows.reduce((s, r) => s + (r.valor_total ?? 0), 0);
108	}
109	
110	interface PerdaDetailQueryRow {
111	  id: number;
112	  quantidade: number | null;
113	  unidade: string | null;
114	  motivo_perda: string;
115	  valor_estimado: number | null;
116	  data_identificacao: string | null;
117	  produto_nome_perda: string | null;
118	  produto_master: { nome: string } | null;
119	}
120	
121	async function loadPerdasDetail(
122	  lojaId: number,
123	  range: TvDateRange,
124	): Promise<{ valor: number; itens: number; list: TvPerdaDetail[] }> {
125	  const bounds = rangeToLocalDayBounds(range);
126	  const rows = await fetchAllPages<PerdaDetailQueryRow>((from, to) =>
127	    supabase
128	      .from('perdas')
129	      .select(
130	        'id, quantidade, unidade, motivo_perda, valor_estimado, data_identificacao, produto_nome_perda, produto_master:produtos_master(nome)',
131	      )
132	      .eq('loja_id', lojaId)
133	      .gte('data_identificacao', bounds.startIso)
134	      .lt('data_identificacao', bounds.endExclusiveIso)
135	      .order('id')
136	      .range(from, to),
137	  );
138	  const list: TvPerdaDetail[] = rows
139	    .map((r) => ({
140	      id: r.id,
141	      // Nome via join produtos_master; fallback pro texto livre da perda
142	      produtoNome: r.produto_master?.nome ?? r.produto_nome_perda ?? '(sem produto)',
143	      quantidade: r.quantidade ?? 0,
144	      unidade: r.unidade,
145	      motivo: r.motivo_perda,
146	      valor: r.valor_estimado ?? 0,
147	      data: r.data_identificacao,
148	    }))
149	    // Mais recente primeiro (nulls de data por último)
150	    .sort((a, b) => (b.data ?? '').localeCompare(a.data ?? ''));
151	  return {
152	    valor: list.reduce((s, p) => s + p.valor, 0),
153	    itens: list.length,
154	    list,
155	  };
156	}
157	
158	async function loadPerdasAggregate(
159	  lojaId: number,
160	  range: TvDateRange,
161	): Promise<number> {
162	  const bounds = rangeToLocalDayBounds(range);
163	  const rows = await fetchAllPages((from, to) =>
164	    supabase
165	      .from('perdas')
166	      .select('loja_id, valor_estimado')
167	      .eq('loja_id', lojaId)
168	      .gte('data_identificacao', bounds.startIso)
169	      .lt('data_identificacao', bounds.endExclusiveIso)
170	      .order('id')
171	      .range(from, to),
172	  );
173	  return aggregatePerdas(rows).total.valor;
174	}
175	
176	interface NotaDetailQueryRow {
177	  id: number;
178	  numero_nota: string;
179	  fornecedor: string;
180	  valor_total: number | null;
181	  data_nota: string;
182	}
183	
184	function notasQueryRange(lojaId: number, range: TvDateRange) {
185	  return (from: number, to: number) =>
186	    supabase
187	      .from('notas_fiscais')
188	      .select('id, numero_nota, fornecedor, valor_total, data_nota')
189	      .eq('loja_id', lojaId)
190	      .gte('data_nota', range.from)
191	      .lte('data_nota', range.to)
192	      .in('status', [...NF_COUNTED_STATUSES])
193	      .not('fornecedor', 'ilike', NF_TRANSFER_SUPPLIER_PATTERN)
194	      .order('id')
195	      .range(from, to);
196	}
197	
198	async function loadNotasDetail(
199	  lojaId: number,
200	  range: TvDateRange,
201	): Promise<{ valor: number; list: TvNotaFiscalDetail[] }> {
202	  const rows = await fetchAllPages<NotaDetailQueryRow>(notasQueryRange(lojaId, range));
203	  const list: TvNotaFiscalDetail[] = rows
204	    .map((r) => ({
205	      id: r.id,
206	      numero: r.numero_nota,
207	      fornecedor: r.fornecedor,
208	      valor: r.valor_total ?? 0,
209	      dataNota: r.data_nota,
210	    }))
211	    .sort((a, b) => b.dataNota.localeCompare(a.dataNota));
212	  return { valor: list.reduce((s, n) => s + n.valor, 0), list };
213	}
214	
215	async function loadNotasAggregate(
216	  lojaId: number,
217	  range: TvDateRange,
218	): Promise<number> {
219	  const rows = await fetchAllPages<NotaDetailQueryRow>(notasQueryRange(lojaId, range));
220	  return rows.reduce((s, r) => s + (r.valor_total ?? 0), 0);
221	}
222	
223	async function loadMovementCounts(
224	  lojaId: number,
225	  range: TvDateRange,
226	): Promise<MovementCounts> {
227	  const bounds = rangeToLocalDayBounds(range);
228	  // Volume real ~380 movimentações/dia (pico >1k): um mês passa FÁCIL de
229	  // 1000 linhas — paginação obrigatória no agregado.
230	  const rows = await fetchAllPages((from, to) =>
231	    supabase
232	      .from('movimentacoes')
233	      .select('loja_id, tipo_movimentacao, data_movimentacao')
234	      .eq('loja_id', lojaId)
235	      .gte('data_movimentacao', bounds.startIso)
236	      .lt('data_movimentacao', bounds.endExclusiveIso)
237	      .order('id')
238	      .range(from, to),
239	  );
240	  const agg = aggregateMovements(rows).get(lojaId);
241	  return { entradas: agg?.entradas ?? 0, saidas: agg?.saidas ?? 0 };
242	}
243	
244	async function loadFeed(lojaId: number, range: TvDateRange): Promise<TvRecentMove[]> {
245	  const bounds = rangeToLocalDayBounds(range);
246	  // Feed do drill-down: query separada com join de nome, SEM paginação
247	  // (cap intencional em TV_DETAIL_FEED_LIMIT — mais recente primeiro).
248	  const { data, error } = await supabase
249	    .from('movimentacoes')
250	    .select(
251	      'loja_id, tipo_movimentacao, data_movimentacao, quantidade, produto_master:produtos_master(nome)',
252	    )
253	    .eq('loja_id', lojaId)
254	    .gte('data_movimentacao', bounds.startIso)
255	    .lt('data_movimentacao', bounds.endExclusiveIso)
256	    .order('data_movimentacao', { ascending: false })
257	    .limit(TV_DETAIL_FEED_LIMIT);
258	  if (error) throw error;
259	  return (data ?? []).map((r) =>
260	    mapFeedRow({
261	      loja_id: r.loja_id,
262	      tipo_movimentacao: r.tipo_movimentacao,
263	      data_movimentacao: r.data_movimentacao,
264	      quantidade: r.quantidade,
265	      produtoNome: r.produto_master?.nome ?? '(sem produto)',
266	    }),
267	  );
268	}
269	
270	async function fetchStoreDetail(
271	  ctx: TvContext,
272	  lojaId: number,
273	  range: TvDateRange,
274	): Promise<StoreDetailPayload> {
275	  const previous = previousRangeSameDuration(range);
276	  const isDegust = ctx.degustLojaIds.has(lojaId);
277	
278	  const [
279	    vendasCur,
280	    vendasPrev,
281	    perdasCur,
282	    perdasPrevValor,
283	    notasCur,
284	    notasPrevValor,
285	    movsCur,
286	    movsPrev,
287	    feed,
288	  ] = await Promise.all([
289	    loadVendasRange(isDegust, lojaId, range),
290	    loadVendasRange(isDegust, lojaId, previous),
291	    loadPerdasDetail(lojaId, range),
292	    loadPerdasAggregate(lojaId, previous),
293	    loadNotasDetail(lojaId, range),
294	    loadNotasAggregate(lojaId, previous),
295	    loadMovementCounts(lojaId, range),
296	    loadMovementCounts(lojaId, previous),
297	    loadFeed(lojaId, range),
298	  ]);
299	
300	  return {
301	    vendas: { valor: vendasCur, previous: vendasPrev },
302	    perdas: {
303	      valor: perdasCur.valor,
304	      itens: perdasCur.itens,
305	      previousValor: perdasPrevValor,
306	    },
307	    compras: { valor: notasCur.valor, previousValor: notasPrevValor },
308	    movimentos: { current: movsCur, previous: movsPrev },
309	    perdasList: perdasCur.list,
310	    notasList: notasCur.list,
311	    feed,
312	  };
313	}
