315	// ─────────────────────────────────────────────────────────────────────────────
316	// Hook
317	// ─────────────────────────────────────────────────────────────────────────────
318	
319	/** Retorno do {@link useTvStoreDetail}. */
320	export interface TvStoreDetailData {
321	  lojaId: number | null;
322	  /** Nome da loja (null enquanto o contexto não carregou / id inválido). */
323	  nome: string | null;
324	  /** Canal de venda da loja (live/defasado/fábrica), ou null sem contexto. */
325	  channel: TvSalesChannel | null;
326	  /** Range aplicado (eco do parâmetro, para rótulos). */
327	  range: TvDateRange;
328	  /** Range anterior de mesma duração usado nos comparativos. */
329	  previousRange: TvDateRange;
330	  /** Vendas somadas no range + delta vs range anterior. */
331	  vendas: { valor: number; deltaPct: number | null };
332	  perdas: TvPerdasSummary;
333	  compras: TvComprasSummary;
334	  /** Contagens de movimentações no range + delta do TOTAL (entr+saídas). */
335	  movimentos: {
336	    entradas: number;
337	    saidas: number;
338	    total: number;
339	    deltaPct: number | null;
340	  };
341	  /** Perdas detalhadas no range (mais recente primeiro). */
342	  perdasList: TvPerdaDetail[];
343	  /** NFs de compra da loja no range (mais recente primeiro). */
344	  notasList: TvNotaFiscalDetail[];
345	  /** Estoque crítico COMPLETO da loja (ordenado por severidade). */
346	  criticalItems: TvCriticalItem[];
347	  /** Feed de movimentações nomeado (até 50, mais recente primeiro). */
348	  feed: TvRecentMove[];
349	  isLoading: boolean;
350	  isError: boolean;
351	}
352	
353	const EMPTY_SUMMARY = { valor: 0, deltaPct: null } as const;
354	
355	/**
356	 * Drill-down de uma loja com range custom. `lojaId` null desabilita as
357	 * queries (página ainda resolvendo o param da rota). Estoque crítico vem da
358	 * MESMA query do painel (cache compartilhado — estado ATUAL, não recortado
359	 * pelo range). Realtime de perdas/movimentações invalida via prefixo
360	 * `storeDetailRoot` no {@link useTvRealtime}.
361	 */
362	export function useTvStoreDetail(
363	  lojaId: number | null,
364	  range: TvDateRange,
365	): TvStoreDetailData {
366	  const ctxQuery = useQuery({
367	    queryKey: tvDashboardKeys.context(),
368	    queryFn: fetchTvContext,
369	    staleTime: TV_QUERY_INTERVALS.slowMs,
370	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
371	  });
372	  const ctx = ctxQuery.data;
373	
374	  const stockQuery = useQuery({
375	    queryKey: tvDashboardKeys.stock(),
376	    queryFn: fetchStockAlerts,
377	    staleTime: TV_QUERY_INTERVALS.slowMs,
378	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
379	    enabled: lojaId != null,
380	  });
381	
382	  const detailQuery = useQuery({
383	    queryKey:
384	      lojaId != null
385	        ? tvDashboardKeys.storeDetail(lojaId, range)
386	        : ([...tvDashboardKeys.storeDetailRoot(), 'disabled'] as const),
387	    queryFn: () => {
388	      if (!ctx || lojaId == null) {
389	        throw new Error('tv-store-detail: contexto/loja ausentes');
390	      }
391	      return fetchStoreDetail(ctx, lojaId, range);
392	    },
393	    enabled: lojaId != null && !!ctx,
394	    staleTime: TV_QUERY_INTERVALS.slowMs,
395	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
396	  });
397	
398	  return useMemo<TvStoreDetailData>(() => {
399	    const previousRange = previousRangeSameDuration(range);
400	    const loja = lojaId != null ? ctx?.lojas.find((l) => l.id === lojaId) : undefined;
401	    const channel: TvSalesChannel | null = !ctx || lojaId == null
402	      ? null
403	      : ctx.factoryLojaId === lojaId
404	        ? 'factory'
405	        : ctx.degustLojaIds.has(lojaId)
406	          ? 'degust-live'
407	          : 'linx-lagged';
408	
409	    const detail = detailQuery.data;
410	    const stockDetail =
411	      lojaId != null
412	        ? buildStockSummary(stockQuery.data ?? []).get(lojaId)
413	        : undefined;
414	
415	    const movsCur = detail?.movimentos.current ?? { entradas: 0, saidas: 0 };
416	    const movsPrev = detail?.movimentos.previous ?? { entradas: 0, saidas: 0 };
417	    const totalCur = movsCur.entradas + movsCur.saidas;
418	    const totalPrev = movsPrev.entradas + movsPrev.saidas;
419	
420	    return {
421	      lojaId,
422	      nome: loja?.nome ?? null,
423	      channel,
424	      range,
425	      previousRange,
426	      vendas: detail
427	        ? {
428	            valor: detail.vendas.valor,
429	            deltaPct: relativeDelta(detail.vendas.valor, detail.vendas.previous),
430	          }
431	        : EMPTY_SUMMARY,
432	      perdas: detail
433	        ? {
434	            valor: detail.perdas.valor,
435	            itens: detail.perdas.itens,
436	            deltaPct: relativeDelta(detail.perdas.valor, detail.perdas.previousValor),
437	          }
438	        : { ...EMPTY_SUMMARY, itens: 0 },
439	      compras: detail
440	        ? {
441	            valor: detail.compras.valor,
442	            deltaPct: relativeDelta(detail.compras.valor, detail.compras.previousValor),
443	          }
444	        : EMPTY_SUMMARY,
445	      movimentos: {
446	        entradas: movsCur.entradas,
447	        saidas: movsCur.saidas,
448	        total: totalCur,
449	        deltaPct: relativeDelta(totalCur, totalPrev > 0 ? totalPrev : null),
450	      },
451	      perdasList: detail?.perdasList ?? [],
452	      notasList: detail?.notasList ?? [],
453	      criticalItems: sortCriticalItems(stockDetail?.itens ?? []),
454	      feed: detail?.feed ?? [],
455	      isLoading:
456	        ctxQuery.isLoading || (lojaId != null && detailQuery.isLoading),
457	      isError: ctxQuery.isError || detailQuery.isError,
458	    };
459	  }, [
460	    lojaId,
461	    range,
462	    ctx,
463	    ctxQuery.isLoading,
464	    ctxQuery.isError,
465	    stockQuery.data,
466	    detailQuery.data,
467	    detailQuery.isLoading,
468	    detailQuery.isError,
469	  ]);
470	}
