91	  // Telas touch (sem hover) não disparam mousemove confiável — o botão
92	  // Metas fica SEMPRE visível, discreto no canto (design.md §8.4).
93	  const [isTouch] = useState(
94	    () =>
95	      typeof window !== 'undefined' &&
