61	
62	type DetailPreset = 'today' | '7d' | 'month' | 'custom';
63	
64	const PRESET_OPTIONS: ReadonlyArray<{ value: Exclude<DetailPreset, 'custom'>; label: string }> = [
65	  { value: 'today', label: 'Hoje' },
66	  { value: '7d', label: '7 dias' },
67	  { value: 'month', label: 'Mês' },
68	];
69	
70	/** Range FECHADO [from, to] (dias locais) para o preset escolhido. */
71	function presetToRange(preset: Exclude<DetailPreset, 'custom'>, now: Date): TvDateRange {
72	  if (preset === 'today') {
73	    const today = toIsoDateLocal(now);
74	    return { from: today, to: today };
75	  }
76	  if (preset === '7d') {
77	    return { from: toIsoDateLocal(addDays(now, -6)), to: toIsoDateLocal(now) };
78	  }
79	  return periodRange('month', now);
80	}
81	
82	/** "01/06 – 05/06/2026" para o range corrente (rótulo honesto do filtro). */
83	function rangeLabel(range: TvDateRange): string {
84	  const from = parseIsoDateLocal(range.from);
85	  const to = parseIsoDateLocal(range.to);
86	  if (range.from === range.to) return format(to, 'dd/MM/yyyy', { locale: ptBR });
87	  return `${format(from, 'dd/MM', { locale: ptBR })} – ${format(to, 'dd/MM/yyyy', { locale: ptBR })}`;
88	}
89	
90	// ─────────────────────────────────────────────────────────────────────────────
91	// Helpers de apresentação
