93	
94	/** R$ completo pt-BR para linhas de lista ("R$ 1.234,56"). */
95	function formatFullBRL(value: number): string {
96	  return value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
97	}
98	
99	/** "dd/MM HH:mm" de um timestamp ISO, ou "—" sem dado. */
100	function formatTimestamp(iso: string | null): string {
101	  if (!iso) return '—';
102	  const d = new Date(iso);
103	  if (Number.isNaN(d.getTime())) return '—';
104	  return format(d, 'dd/MM HH:mm', { locale: ptBR });
105	}
106	
107	/** "dd/MM/yyyy" de uma data-dia local (YYYY-MM-DD). */
108	function formatDay(isoDate: string): string {
109	  return format(parseIsoDateLocal(isoDate), 'dd/MM/yyyy', { locale: ptBR });
110	}
111	
112	/**
113	 * Delta % vs período anterior dos KPIs. Neutro por padrão; âmbar SÓ em
114	 * desvio (perdas subindo / vendas caindo forte). Sem base → texto honesto.
115	 */
116	function DetailDelta({
117	  deltaPct,
118	  tone = 'neutral',
119	}: {
120	  deltaPct: number | null;
121	  tone?: 'neutral' | 'up-is-bad' | 'down-is-bad';
122	}) {
123	  if (deltaPct == null) {
124	    return <span className="text-xs text-muted-foreground">sem base anterior</span>;
125	  }
126	  const isAmber =
127	    (tone === 'up-is-bad' && deltaPct > 0) ||
128	    (tone === 'down-is-bad' && deltaPct <= -15);
129	  const Icon = deltaPct < 0 ? ArrowDown : ArrowUp;
130	  return (
131	    <span
132	      className={cn(
133	        'inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium tabular-nums',
134	        isAmber
135	          ? 'bg-amber-50 text-amber-600 dark:bg-amber-900/20'
136	          : 'bg-[#57715B]/8 text-[#5F6F63] dark:text-[#8FAE94]',
137	      )}
138	    >
139	      <Icon className="h-3 w-3 shrink-0" aria-hidden />
140	      {formatDeltaPct(deltaPct)} vs anterior
141	    </span>
142	  );
143	}
