145	/** KPI card glass (padrão do design system, com watermark de ícone). */
146	function KpiCard({
147	  icon: Icon,
148	  label,
149	  value,
150	  sub,
151	  delta,
152	  testId,
153	}: {
154	  icon: typeof Banknote;
