164	      data-testid={testId}
165	    >
166	      <Icon
167	        className="absolute right-3 top-3 h-10 w-10 text-[#57715B] opacity-10 transition-opacity group-hover:opacity-20"
168	        aria-hidden
169	      />
170	      <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
171	        {label}
172	      </p>
