2	 * @module features/tv-dashboard/ui/TvFabricaColumn
3	 *
4	 * Coluna VERTICAL da fábrica (v3 — posição 6): mesma anatomia da coluna de
5	 * loja, com PRODUÇÃO do dia + EXPEDIÇÕES no lugar de vendas. Hairline GOLD
6	 * de assinatura. Clicável → `/tv/loja/:id` (drill-down da unidade).
7	 */
8	
9	import { ArrowDownRight, ArrowUpRight, Factory } from 'lucide-react';
10	import type { TvFactoryData, TvFreshness, TvPeriod } from '../model/types';
11	import { parseIsoDateLocal, toIsoDateLocal } from '../model/tvMath';
12	import { TvSourceChip, TvStateChip } from './TvChips';
13	import {
14	  TvColumnBipLine,
15	  TvColumnCritical,
16	  TvColumnFeed,
17	  TvColumnLabel,
18	  TvColumnPerdas,
19	  TvUnitColumn,
20	} from './TvColumnParts';
21	import { formatInt, formatWeekdayDayMonth } from './tvFormat';
22	import { useCountUp } from './useCountUp';
23	
24	interface TvFabricaColumnProps {
25	  factory: TvFactoryData;
26	  freshness: TvFreshness;
27	  /** Período do filtro global (rótulo honesto das perdas). */
28	  period: TvPeriod;
29	  now: Date;
30	}
31	
32	/** Coluna da fábrica: nunca tem venda — produção/expedições + operação. */
33	export function TvFabricaColumn({
34	  factory,
35	  freshness,
36	  period,
37	  now,
38	}: TvFabricaColumnProps) {
39	  const producao = factory.producao;
40	  const unidadesAnim = Math.round(useCountUp(producao?.totalUnidades ?? 0));
41	
42	  const todayIso = toIsoDateLocal(now);
43	  const isToday = producao?.dataReferencia === todayIso;
44	  const refLabel =
45	    producao && !isToday
46	      ? formatWeekdayDayMonth(parseIsoDateLocal(producao.dataReferencia))
47	      : null;
48	
49	  return (
50	    <TvUnitColumn
51	      lojaId={factory.lojaId}
52	      nome={factory.nome}
53	      rag={factory.rag}
54	      goldHairline
55	      testId="tv-fabrica-column"
56	    >
